-- ============================================================================
-- LAYOVER — PostgreSQL schema for Supabase
-- Run this file first in the Supabase SQL editor (or psql against your DB).
-- ============================================================================
-- Conventions used throughout:
--  * auth.uid() from Supabase Auth governs who can read/write each table.
--  * "uuid" primary keys generated by gen_random_uuid().
--  * created_at / updated_at timestamps on every table.
--  * status / enum-ish values kept as text + CHECK constraints (easy MVP).
-- ============================================================================

create extension if not exists "uuid-ossp";

-- ----------------------------------------------------------------------------
-- profiles: one row per authenticated Supabase user
-- NOTE: we deliberately do NOT store passwords or government ID data.
--       auth.users (managed by Supabase) holds credentials; profiles holds only
--       what our app needs: display name + verification status + interests.
-- ----------------------------------------------------------------------------
create table public.profiles (
  id                  uuid primary key references auth.users (id) on delete cascade,
  display_name        text not null,
  avatar_url          text,
  verification_status text not null default 'unverified'
                      check (verification_status in ('unverified','pending','verified')),
  interests           text[] not null default '{}',
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

-- ----------------------------------------------------------------------------
-- layovers: one traveller's time window at one airport
-- ----------------------------------------------------------------------------
create table public.layovers (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles (id) on delete cascade,
  airport_code   text not null,
  arrival_time   timestamptz not null,
  departure_time timestamptz not null,
  baggage_count  int  not null default 0 check (baggage_count >= 0),
  budget_total   numeric(10,2) not null default 0 check (budget_total >= 0),
  currency       text not null default 'USD' check (length(currency) = 3),
  interests      text[] not null default '{}',
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint layovers_time_order check (departure_time > arrival_time)
);

create index layovers_user_idx    on public.layovers (user_id);
create index layovers_airport_idx on public.layovers (airport_code, arrival_time, departure_time);

-- ----------------------------------------------------------------------------
-- storage_facilities: luggage storage providers (SIMULATED provider list)
-- ----------------------------------------------------------------------------
create table public.storage_facilities (
  id                 uuid primary key default gen_random_uuid(),
  provider_name      text not null,
  airport_code       text not null,
  location           text not null,          -- human-readable, e.g. "Terminal 2, Level 1"
  lat                numeric(9,6),
  lng                numeric(9,6),
  price_per_bag_hour numeric(10,2) not null check (price_per_bag_hour >= 0),
  currency           text not null default 'USD' check (length(currency) = 3),
  capacity_total     int not null check (capacity_total >= 0),
  share_max_users    int not null default 4 check (share_max_users >= 1),
  share_min_users    int not null default 2 check (share_min_users >= 1),
  opening_time       time not null default '00:00:00',
  closing_time       time not null default '23:59:59',
  sharing_allowed    boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint storage_share_range check (share_min_users <= share_max_users)
);

create index storage_facilities_airport_idx on public.storage_facilities (airport_code, price_per_bag_hour);

-- ----------------------------------------------------------------------------
-- matches: candidate traveller pairs produced by the matching engine
-- ----------------------------------------------------------------------------
create table public.matches (
  id                 uuid primary key default gen_random_uuid(),
  layover_a_id       uuid not null references public.layovers (id) on delete cascade,
  layover_b_id       uuid not null references public.layovers (id) on delete cascade,
  user_a_id          uuid not null references public.profiles (id) on delete cascade,
  user_b_id          uuid not null references public.profiles (id) on delete cascade,
  score              numeric(5,2) not null check (score >= 0 and score <= 100),
  status             text not null default 'proposed'
                     check (status in ('proposed','accepted','rejected','expired')),
  simulated          boolean not null default false,  -- SIMULATED flag
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint matches_distinct_layovers check (layover_a_id <> layover_b_id),
  constraint matches_distinct_users    check (user_a_id <> user_b_id)
);

-- avoid duplicate pair rows from racing matchers
create unique index matches_pair_uniq on public.matches (
  least(user_a_id,user_b_id), greatest(user_a_id,user_b_id), least(layover_a_id,layover_b_id), greatest(layover_a_id,layover_b_id)
);
create index matches_user_a_idx on public.matches (user_a_id, status);
create index matches_user_b_idx on public.matches (user_b_id, status);

-- ----------------------------------------------------------------------------
-- bookings: a reservation against one storage facility
-- ----------------------------------------------------------------------------
create table public.bookings (
  id                 uuid primary key default gen_random_uuid(),
  facility_id        uuid not null references public.storage_facilities (id) on delete restrict,
  created_by         uuid not null references public.profiles (id) on delete cascade,
  layover_id         uuid not null references public.layovers (id) on delete cascade,
  starts_at          timestamptz not null,
  ends_at            timestamptz not null,
  total_price        numeric(10,2) not null check (total_price >= 0),
  currency           text not null default 'USD' check (length(currency) = 3),
  status             text not null default 'pending'
                     check (status in ('pending','confirmed','cancelled','expired')),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint bookings_time_order check (ends_at > starts_at)
);

create index bookings_created_by_idx   on public.bookings (created_by, status);
create index bookings_facility_idx     on public.bookings (facility_id, starts_at, ends_at);

-- ----------------------------------------------------------------------------
-- booking_members: who shares the locker, their cost share, and permissions
-- ----------------------------------------------------------------------------
create table public.booking_members (
  id             uuid primary key default gen_random_uuid(),
  booking_id     uuid not null references public.bookings (id) on delete cascade,
  user_id        uuid not null references public.profiles (id) on delete cascade,
  cost_share     numeric(10,2) not null check (cost_share >= 0),
  currency       text not null default 'USD' check (length(currency) = 3),
  payment_status text not null default 'unpaid'
                 check (payment_status in ('unpaid','paid','refunded')),
  can_retrieve   boolean not null default false,   -- can this member unlock the locker?
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint booking_members_unique_unique unique (booking_id, user_id)
);

create index booking_members_user_idx on public.booking_members (user_id);

-- ----------------------------------------------------------------------------
-- payments: simulated payment records (no real money moves)
-- ----------------------------------------------------------------------------
create table public.payments (
  id             uuid primary key default gen_random_uuid(),
  booking_id     uuid not null references public.bookings (id) on delete cascade,
  payer_id       uuid not null references public.profiles (id) on delete cascade,
  amount         numeric(10,2) not null check (amount >= 0),
  currency       text not null default 'USD' check (length(currency) = 3),
  status         text not null default 'simulated_pending'
                 check (status in ('simulated_pending','simulated_paid','simulated_refunded','failed')),
  transaction_ref text not null default ('SIM-' || replace(gen_random_uuid()::text, '-', '')),
  simulated      boolean not null default true,    -- SIMULATED flag, always true in MVP
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index payments_booking_idx  on public.payments (booking_id);
create index payments_payer_idx    on public.payments (payer_id);

-- ----------------------------------------------------------------------------
-- itineraries: suggested activities + timing for a layover
-- ----------------------------------------------------------------------------
create table public.itineraries (
  id             uuid primary key default gen_random_uuid(),
  layover_id     uuid not null references public.layovers (id) on delete cascade,
  user_id        uuid not null references public.profiles (id) on delete cascade,
  activities     jsonb not null default '[]',      -- [{name, start, end, travel_minutes}]
  return_time    timestamptz not null,             -- when user must be back at airport
  estimated_total_cost numeric(10,2) not null default 0,
  currency       text not null default 'USD' check (length(currency) = 3),
  is_mock        boolean not null default true,    -- SIMULATED activity catalog
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index itineraries_layover_idx on public.itineraries (layover_id);
create index itineraries_user_idx    on public.itineraries (user_id);

-- ----------------------------------------------------------------------------
-- access_logs: audit trail for authorized booking actions
-- ----------------------------------------------------------------------------
create table public.access_logs (
  id             uuid primary key default gen_random_uuid(),
  booking_id     uuid references public.bookings (id) on delete cascade,
  user_id        uuid not null references public.profiles (id) on delete cascade,
  action         text not null,
  metadata       jsonb not null default '{}',
  created_at     timestamptz not null default now()
);

create index access_logs_booking_idx on public.access_logs (booking_id, created_at desc);
create index access_logs_user_idx    on public.access_logs (user_id, created_at desc);

-- ============================================================================
-- Row Level Security
-- ============================================================================
alter table public.profiles           enable row level security;
alter table public.layovers           enable row level security;
alter table public.storage_facilities enable row level security;
alter table public.matches            enable row level security;
alter table public.bookings           enable row level security;
alter table public.booking_members    enable row level security;
alter table public.payments           enable row level security;
alter table public.itineraries        enable row level security;
alter table public.access_logs        enable row level security;

-- profiles: anyone logged-in can read profiles (needed for matching display);
-- users can only update their own.
create policy "profiles_select_for_authenticated" on public.profiles
  for select using (auth.role() = 'authenticated');
create policy "profiles_self_update" on public.profiles
  for update using (auth.uid() = id) with check (auth.uid() = id);
create policy "profiles_self_insert" on public.profiles
  for insert with check (auth.uid() = id);

-- layovers: visible to the owner AND to public discover feeds (read-all MVP).
create policy "layovers_select_authenticated" on public.layovers
  for select using (auth.role() = 'authenticated');
create policy "layovers_own_insert" on public.layovers
  for insert with check (auth.uid() = user_id);
create policy "layovers_own_update" on public.layovers
  for update using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "layovers_own_delete" on public.layovers
  for delete using (auth.uid() = user_id);

-- storage_facilities: read-only to authenticated users (admins maintain via seed).
create policy "storage_select_authenticated" on public.storage_facilities
  for select using (auth.role() = 'authenticated');

-- matches: all authenticated users can read (needed for browse/discover);
-- only the two participants can change status.
create policy "matches_select_authenticated" on public.matches
  for select using (auth.role() = 'authenticated');
create policy "matches_participant_update" on public.matches
  for update using (auth.uid() in (user_a_id, user_b_id))
  with check (auth.uid() in (user_a_id, user_b_id));

-- bookings: participants can see their own bookings; only creator can modify.
create policy "bookings_select_authenticated" on public.bookings
  for select using (auth.role() = 'authenticated');
create policy "bookings_own_insert" on public.bookings
  for insert with check (auth.uid() = created_by);
create policy "bookings_own_update" on public.bookings
  for update using (auth.uid() = created_by) with check (auth.uid() = created_by);
create policy "bookings_own_delete" on public.bookings
  for delete using (auth.uid() = created_by);

-- booking_members: read all; only booking creator can insert/update members.
create policy "booking_members_select_authenticated" on public.booking_members
  for select using (auth.role() = 'authenticated');
create policy "booking_members_creator_write" on public.booking_members
  for all using (
    exists (select 1 from public.bookings b
            where b.id = booking_members.booking_id and b.created_by = auth.uid())
  ) with check (
    exists (select 1 from public.bookings b
            where b.id = booking_members.booking_id and b.created_by = auth.uid())
  );

-- payments: only the payer and creator can see their payment records.
create policy "payments_payer_or_creator_select" on public.payments
  for select using (
    auth.uid() = payer_id
    or exists (select 1 from public.bookings b
               where b.id = payments.booking_id and b.created_by = auth.uid())
  );

-- itineraries: owner-only.
create policy "itineraries_select_authenticated" on public.itineraries
  for select using (auth.role() = 'authenticated');
create policy "itineraries_own_write" on public.itineraries
  for all using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- access_logs: owner-visible (created in app flows that the user triggers).
create policy "access_logs_select_authenticated" on public.access_logs
  for select using (auth.role() = 'authenticated');
create policy "access_logs_insert_authenticated" on public.access_logs
  for insert with check (auth.uid() = user_id);

-- ============================================================================
-- Triggers: keep updated_at fresh
-- ============================================================================
create or replace function public.set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

do $$
declare t text;
begin
  foreach t in array array['profiles','layovers','storage_facilities','matches',
                           'bookings','booking_members','payments','itineraries']
  loop
    execute format(
      'drop trigger if exists trg_%1$s_updated_at on public.%1$s;
       create trigger trg_%1$s_updated_at before update on public.%1$s
       for each row execute function public.set_updated_at();', t);
  end loop;
end;
$$;

-- ============================================================================
-- NOTE — Supabase Auth setup
-- You must enable "Email" provider in Supabase dashboard > Auth > Providers.
-- profiles.id matches auth.users.id; the app creates the matching profile row
-- on first sign-up. Primary key + RLS policies above keep data safe.
-- ============================================================================
